#include <stdio.h>
#include <string.h>

#define MAXN 105

typedef struct {
    char name[24];
    int total;
} STUDENT;

/* 返回 1 表示 a 应排在 b 之前：总分降序，总分相同按姓名字典序升序 */
static int before(const STUDENT *a, const STUDENT *b)
{
    if (a->total != b->total) {
        return a->total > b->total;
    }
    return strcmp(a->name, b->name) < 0;
}

int main(void)
{
    STUDENT a[MAXN];
    STUDENT key;
    int n, i, j;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%s %d", a[i].name, &a[i].total);
    }

    /* 直接插入排序：整个结构体一起移动，不拆成两个平行数组 */
    for (i = 1; i < n; i++) {
        key = a[i];
        j = i - 1;
        while (j >= 0 && !before(&a[j], &key)) {
            a[j + 1] = a[j];
            j--;
        }
        a[j + 1] = key;
    }

    for (i = 0; i < n; i++) {
        printf("%s %d\n", a[i].name, a[i].total);
    }
    return 0;
}

#include <stdio.h>

#define MAXN 105

typedef struct {
    char id[16];
    int total;      /* 综合成绩 */
    int p1;         /* 笔试成绩 */
    int p2;         /* 项目成绩 */
} STU;

/* 交换两个结构体所指向的内容 */
void Swap(STU *s1, STU *s2)
{
    STU t = *s1;
    *s1 = *s2;
    *s2 = t;
}

/* 若 s1 应排在 s2 之前返回 1，否则返回 0 */
int Comp(STU *s1, STU *s2)
{
    if (s1->total != s2->total) {
        return s1->total > s2->total;
    }
    return s1->p1 > s2->p1;
}

/* 选择排序，排序规则全部交给 Comp/Swap */
void Sort(STU a[], int size)
{
    int i, j;
    for (i = 0; i < size; i++) {
        for (j = i + 1; j < size; j++) {
            if (Comp(&a[j], &a[i])) {
                Swap(&a[i], &a[j]);
            }
        }
    }
}

int main(void)
{
    STU stu[MAXN];
    int n, i;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%s %d %d", stu[i].id, &stu[i].p1, &stu[i].p2);
        stu[i].total = stu[i].p1 + stu[i].p2;
    }

    Sort(stu, n);

    for (i = 0; i < n; i++) {
        printf("%s %d %d %d\n", stu[i].id, stu[i].total, stu[i].p1, stu[i].p2);
    }
    return 0;
}

#include <stdio.h>
#include <math.h>

/* 复数类型：数据成员只有 re、im，操作全部写成独立函数，模拟「类」 */
typedef struct {
    double re;
    double im;
} Complex;

Complex c_add(Complex a, Complex b)
{
    Complex r;
    r.re = a.re + b.re;
    r.im = a.im + b.im;
    return r;
}

Complex c_sub(Complex a, Complex b)
{
    Complex r;
    r.re = a.re - b.re;
    r.im = a.im - b.im;
    return r;
}

Complex c_mul(Complex a, Complex b)
{
    Complex r;
    r.re = a.re * b.re - a.im * b.im;
    r.im = a.re * b.im + a.im * b.re;
    return r;
}

double c_abs(Complex z)
{
    return sqrt(z.re * z.re + z.im * z.im);
}

void c_print(Complex z)
{
    printf("(%.2f,%.2f)\n", z.re, z.im);
}

int main(void)
{
    Complex a, b;
    char op;
    int n, i;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf(" %c", &op);
        scanf("%lf %lf", &a.re, &a.im);
        if (op == '|') {
            printf("|z|=%.2f\n", c_abs(a));
            continue;
        }
        scanf("%lf %lf", &b.re, &b.im);
        if (op == '+') {
            c_print(c_add(a, b));
        } else if (op == '-') {
            c_print(c_sub(a, b));
        } else {
            c_print(c_mul(a, b));
        }
    }
    return 0;
}

#include <stdio.h>

typedef struct {
    int y;
    int m;
    int d;
} Date;

static const char *WEEK[7] = {"SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"};

static int is_leap(int y)
{
    return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
}

/* 把日期换算成「公元 1 年 1 月 1 日以来的第几天」，相减即天数差 */
static long long date_days(Date t)
{
    static const int mdays[13] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    long long y = t.y - 1;
    long long days = y * 365 + y / 4 - y / 100 + y / 400;
    int m;

    for (m = 1; m < t.m; m++) {
        days += mdays[m];
        if (m == 2 && is_leap(t.y)) {
            days += 1;
        }
    }
    days += t.d;
    return days;
}

/* 0 = 星期日，1 = 星期一，……，6 = 星期六 */
static int weekday(Date t)
{
    return (int)(date_days(t) % 7);
}

/* a 比 b 早返回 -1，相同返回 0，晚返回 1 */
static int date_compare(Date a, Date b)
{
    long long da = date_days(a);
    long long db = date_days(b);
    if (da < db) {
        return -1;
    }
    if (da > db) {
        return 1;
    }
    return 0;
}

int main(void)
{
    Date a, b, early;
    long long diff;

    scanf("%d %d %d", &a.y, &a.m, &a.d);
    scanf("%d %d %d", &b.y, &b.m, &b.d);

    if (date_compare(a, b) <= 0) {
        early = a;
    } else {
        early = b;
    }

    diff = date_days(a) - date_days(b);
    if (diff < 0) {
        diff = -diff;
    }

    printf("Earlier:%04d-%02d-%02d\n", early.y, early.m, early.d);
    printf("Days:%lld\n", diff);
    printf("Weekday:%s\n", WEEK[weekday(early)]);
    return 0;
}

#include <stdio.h>
#include <math.h>

typedef struct {
    double x;
    double y;
} Point;

typedef struct {
    Point lo;   /* 左下角 */
    Point hi;   /* 右上角 */
} Rect;

static Point make_point(double x, double y)
{
    Point p;
    p.x = x;
    p.y = y;
    return p;
}

/* 点在矩形内（含边界）返回 1 */
static int rect_contains(Rect r, Point p)
{
    return p.x >= r.lo.x && p.x <= r.hi.x &&
           p.y >= r.lo.y && p.y <= r.hi.y;
}

/* 点到矩形的最短距离：点在矩形内为 0，否则取到最近边的欧氏距离 */
static double rect_distance(Rect r, Point p)
{
    double dx = 0.0;
    double dy = 0.0;

    if (p.x < r.lo.x) {
        dx = r.lo.x - p.x;
    } else if (p.x > r.hi.x) {
        dx = p.x - r.hi.x;
    }
    if (p.y < r.lo.y) {
        dy = r.lo.y - p.y;
    } else if (p.y > r.hi.y) {
        dy = p.y - r.hi.y;
    }
    return sqrt(dx * dx + dy * dy);
}

int main(void)
{
    Rect r;
    Point p;
    int n, i;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        double x1, y1, x2, y2, px, py;
        scanf("%lf %lf %lf %lf %lf %lf", &x1, &y1, &x2, &y2, &px, &py);
        r.lo = make_point(x1, y1);
        r.hi = make_point(x2, y2);
        p = make_point(px, py);
        if (rect_contains(r, p)) {
            printf("IN %.2f\n", 0.0);
        } else {
            printf("OUT %.2f\n", rect_distance(r, p));
        }
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXN 105

/* 内层结构体：三门课成绩 */
typedef struct {
    int math;
    int english;
    int c;
} SCORE;

/* 外层结构体：学生信息里嵌套一个 SCORE */
typedef struct {
    char name[24];
    char id[24];
    SCORE sc;
    int total;
    double avg;
} STUDENT;

/* 返回最高分科目名，并列时按 数学 > 英语 > C语言 的顺序取 */
static const char *best_subject(SCORE sc)
{
    if (sc.math >= sc.english && sc.math >= sc.c) {
        return "Math";
    }
    if (sc.english >= sc.c) {
        return "English";
    }
    return "C";
}

/* 总成绩降序，同分按姓名升序 */
static int before(const STUDENT *a, const STUDENT *b)
{
    if (a->total != b->total) {
        return a->total > b->total;
    }
    return strcmp(a->name, b->name) < 0;
}

int main(void)
{
    STUDENT a[MAXN];
    STUDENT key;
    int n, i, j;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%s %s %d %d %d", a[i].name, a[i].id,
              &a[i].sc.math, &a[i].sc.english, &a[i].sc.c);
        a[i].total = a[i].sc.math + a[i].sc.english + a[i].sc.c;
        a[i].avg = a[i].total / 3.0;
    }

    for (i = 1; i < n; i++) {
        key = a[i];
        j = i - 1;
        while (j >= 0 && !before(&a[j], &key)) {
            a[j + 1] = a[j];
            j--;
        }
        a[j + 1] = key;
    }

    for (i = 0; i < n; i++) {
        printf("%d %s %d %.2f %s\n", i + 1, a[i].name, a[i].total,
               a[i].avg, best_subject(a[i].sc));
    }
    return 0;
}

