/* 销量降序 -> 价格升序 -> 书名字典序升序 */
static int before(const BOOK *a, const BOOK *b)
{
    if (a->sales != b->sales) {
        return a->sales > b->sales;
    }
    if (a->price != b->price) {
        return a->price < b->price;
    }
    return strcmp(a->name, b->name) < 0;
}

int main(void)
