    }

    for (i = 1; i < n; i++) {
        key = a[i];
        j = i - 1;
        while (j >= 0 && !before(&a[j], &key)) {
            a[j + 1] = a[j];
            j--;
        }
        a[j + 1] = key;
    }

    for (i = 0; i < n; i++) {
        printf("%s %d %.2f\n", a[i].name, a[i].sales, a[i].price);
    }
    return 0;
}

#include <stdio.h>

#define MAXN 1005

/* 枚举：两种流水类型 */
typedef enum {
    DEPOSIT = 0,    /* 存入 */
    SPEND = 1       /* 消费 */
} OP;

typedef struct {
    OP op;
    int amount;
} RECORD;

static char op_char(OP op)
{
    switch (op) {
    case DEPOSIT:
        return 'D';
    case SPEND:
        return 'S';
    default:
        return '?';
    }
}

int main(void)
{
    RECORD rec[MAXN];
    int n, i;
    int balance = 0;
    int failed = 0;
    int deposits = 0;
    int max_spend = 0;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        char c;
        scanf(" %c %d", &c, &rec[i].amount);
        switch (c) {
        case 'D':
            rec[i].op = DEPOSIT;
            break;
        case 'S':
            rec[i].op = SPEND;
            break;
        default:
            rec[i].op = DEPOSIT;
            break;
        }
    }

    for (i = 0; i < n; i++) {
        switch (rec[i].op) {
        case DEPOSIT:
            balance += rec[i].amount;
            deposits += rec[i].amount;
            break;
        case SPEND:
            if (rec[i].amount > balance) {
                failed++;
            } else {
                balance -= rec[i].amount;
                if (rec[i].amount > max_spend) {
                    max_spend = rec[i].amount;
                }
            }
            break;
        }
        printf("%c %d %d\n", op_char(rec[i].op), rec[i].amount, balance);
    }

    printf("Balance=%d\n", balance);
    printf("Failed=%d\n", failed);
    printf("Deposits=%d\n", deposits);
    printf("MaxSpend=%d\n", max_spend);
    return 0;
}

#include <stdio.h>

#define CAP 100     /* 栈的容量 */

/* 用数组实现栈：data 存元素，top 同时表示「栈顶下标 + 1」和元素个数 */
typedef struct {
    int data[CAP];
    int top;
} Stack;

void stack_init(Stack *s)
{
    s->top = 0;
}

/* 压栈成功返回 1，栈满返回 0 */
int stack_push(Stack *s, int x)
{
    if (s->top >= CAP) {
        return 0;
    }
    s->data[s->top] = x;
    s->top++;
    return 1;
}

/* 弹栈成功返回 1，并把弹出的值写入 *x；栈空返回 0 */
int stack_pop(Stack *s, int *x)
{
    if (s->top == 0) {
        return 0;
    }
    s->top--;
    *x = s->data[s->top];
    return 1;
}

/* 只看栈顶，不弹出 */
int stack_top(const Stack *s, int *x)
{
    if (s->top == 0) {
        return 0;
    }
    *x = s->data[s->top - 1];
    return 1;
}

int stack_empty(const Stack *s)
{
    return s->top == 0;
}

int stack_size(const Stack *s)
{
    return s->top;
}

int main(void)
{
    Stack st;
    int n, i;

    stack_init(&st);
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        int cmd, x;
        scanf("%d", &cmd);
        if (cmd == 1) {
            scanf("%d", &x);
            if (stack_push(&st, x)) {
                printf("Push %d ok\n", x);
            } else {
                printf("Full\n");
            }
        } else if (cmd == 2) {
            if (stack_pop(&st, &x)) {
                printf("Pop %d\n", x);
            } else {
                printf("Empty\n");
            }
        } else if (cmd == 3) {
            if (stack_top(&st, &x)) {
                printf("Top %d\n", x);
            } else {
                printf("Empty\n");
            }
        } else if (cmd == 4) {
            printf("Empty %s\n", stack_empty(&st) ? "yes" : "no");
        } else {
            printf("Size %d\n", stack_size(&st));
        }
    }
    return 0;
}

#include <stdio.h>

#define CAP 205     /* 队列容量，需大于人数 n */

/* 循环队列：head 指向队头，tail 指向下一个空位，count 记录元素个数 */
typedef struct {
    int data[CAP];
    int head;
    int tail;
    int count;
} Queue;

void queue_init(Queue *q)
{
    q->head = 0;
    q->tail = 0;
    q->count = 0;
}

int queue_push(Queue *q, int x)
{
    if (q->count >= CAP) {
        return 0;
    }
    q->data[q->tail] = x;
    q->tail = (q->tail + 1) % CAP;   /* 到末尾回头，实现循环复用 */
    q->count++;
    return 1;
}

int queue_pop(Queue *q, int *x)
{
    if (q->count == 0) {
        return 0;
    }
    *x = q->data[q->head];
    q->head = (q->head + 1) % CAP;
    q->count--;
    return 1;
}

int queue_front(const Queue *q, int *x)
{
    if (q->count == 0) {
        return 0;
    }
    *x = q->data[q->head];
    return 1;
}

int queue_empty(const Queue *q)
{
    return q->count == 0;
}

int queue_size(const Queue *q)
{
    return q->count;
}

int main(void)
{
    Queue q;
    int n, m, i, k;
    int x = 0;
    int first = 1;

    scanf("%d %d", &n, &m);
    queue_init(&q);
    for (i = 1; i <= n; i++) {
        queue_push(&q, i);
    }

    printf("Order:");
    while (!queue_empty(&q)) {
        /* 前 m-1 个人从队头取出再放到队尾，第 m 个人出列 */
        for (k = 1; k < m; k++) {
            queue_pop(&q, &x);
            queue_push(&q, x);
        }
        queue_pop(&q, &x);
        if (!first) {
            printf(" ");
        }
        printf("%d", x);
        first = 0;
    }
    printf("\n");
    printf("Last:%d\n", x);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXS 100    /* 最多管理的学生人数 */
#define MAXL 16     /* 学号、姓名的最大长度 + 余量 */

typedef struct {
    char id[MAXL];
    char name[MAXL];
    int math;
    int eng;
    int comp;
} STUDENT;

/* 学生集合：结构体数组 + 当前人数，一组函数负责增删改查 */
typedef struct {
    STUDENT stu[MAXS];
    int count;
} SYSTEM;

void sys_init(SYSTEM *sys)
{
    sys->count = 0;
}

int sys_find(const SYSTEM *sys, const char *id)
{
    int i;
    for (i = 0; i < sys->count; i++) {
        if (strcmp(sys->stu[i].id, id) == 0) {
            return i;
        }
    }
    return -1;
}

double stu_average(const STUDENT *s)
{
    return (s->math + s->eng + s->comp) / 3.0;
}

int sys_add(SYSTEM *sys, const char *id, const char *name, int a, int b, int c)
{
    STUDENT *s;
    if (sys->count >= MAXS || sys_find(sys, id) >= 0) {
        return 0;
    }
    s = &sys->stu[sys->count];
    strcpy(s->id, id);
    strcpy(s->name, name);
    s->math = a;
    s->eng = b;
    s->comp = c;
    sys->count++;
    return 1;
}

int sys_delete(SYSTEM *sys, const char *id)
{
    int pos = sys_find(sys, id);
    int i;
    if (pos < 0) {
        return 0;
    }
    for (i = pos; i < sys->count - 1; i++) {
        sys->stu[i] = sys->stu[i + 1];
    }
    sys->count--;
    return 1;
}

int sys_update(SYSTEM *sys, const char *id, int a, int b, int c)
{
    int pos = sys_find(sys, id);
    if (pos < 0) {
        return 0;
    }
    sys->stu[pos].math = a;
    sys->stu[pos].eng = b;
    sys->stu[pos].comp = c;
    return 1;
}

void sys_show(const SYSTEM *sys, const char *id)
{
    int pos = sys_find(sys, id);
    const STUDENT *s;
    if (pos < 0) {
        printf("Not exist\n");
        return;
    }
    s = &sys->stu[pos];
    printf("ID:%s\n", s->id);
    printf("Name:%s\n", s->name);
    printf("Average:%.1f\n", stu_average(s));
}

/* 按平均分降序输出全体，同分按学号升序（排序在副本上做，不改动原数组） */
void sys_list(const SYSTEM *sys)
{
    STUDENT tmp[MAXS];
    int n = sys->count;
    int i, j;

    memcpy(tmp, sys->stu, sizeof(STUDENT) * (size_t)n);
    for (i = 1; i < n; i++) {
        STUDENT key = tmp[i];
        j = i - 1;
        while (j >= 0) {
            double ka = stu_average(&key);
            double ja = stu_average(&tmp[j]);
            int put = (ja < ka) || (ja == ka && strcmp(tmp[j].id, key.id) > 0);
            if (!put) {
                break;
            }
            tmp[j + 1] = tmp[j];
            j--;
        }
        tmp[j + 1] = key;
    }
    for (i = 0; i < n; i++) {
        printf("%s %s %.1f\n", tmp[i].id, tmp[i].name, stu_average(&tmp[i]));
    }
}

int main(void)
{
    SYSTEM sys;
    int n, i;

    sys_init(&sys);
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        int cmd;
        scanf("%d", &cmd);
        if (cmd == 1) {
            char id[MAXL], name[MAXL];
            int a, b, c;
            scanf("%s %s %d %d %d", id, name, &a, &b, &c);
            printf("%s\n", sys_add(&sys, id, name, a, b, c) ? "Add success" : "Add failed");
        } else if (cmd == 2) {
            char id[MAXL];
            scanf("%s", id);
            printf("%s\n", sys_delete(&sys, id) ? "Delete success" : "Not exist");
        } else if (cmd == 3) {
            char id[MAXL];
            int a, b, c;
            scanf("%s %d %d %d", id, &a, &b, &c);
            printf("%s\n", sys_update(&sys, id, a, b, c) ? "Update success" : "Not exist");
        } else if (cmd == 4) {
            char id[MAXL];
            scanf("%s", id);
            sys_show(&sys, id);
        } else if (cmd == 5) {
            sys_list(&sys);
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char name[20];
    int a;       /* 第一场成绩 */
    int b;       /* 第二场成绩 */
    int total;
} PLAYER;

/* 总分降序 -> 第一场成绩降序 -> 姓名升序 */
static int cmp(const void *p, const void *q)
{
    const PLAYER *x = (const PLAYER *)p;
    const PLAYER *y = (const PLAYER *)q;

    if (x->total != y->total) {
        return y->total - x->total;
    }
    if (x->a != y->a) {
        return y->a - x->a;
    }
    return strcmp(x->name, y->name);
}

int main(void)
{
    PLAYER *arr;
    int n, k, i;

    if (scanf("%d %d", &n, &k) != 2) {
        return 0;
    }
    if (n <= 0) {
        return 0;
    }

    /* 按人数动态申请结构体数组，n 可达 200000 */
    arr = (PLAYER *)malloc((size_t)n * sizeof(PLAYER));
    if (arr == NULL) {
        return 1;
    }

    for (i = 0; i < n; i++) {
        scanf("%s %d %d", arr[i].name, &arr[i].a, &arr[i].b);
        arr[i].total = arr[i].a + arr[i].b;
    }

    qsort(arr, (size_t)n, sizeof(PLAYER), cmp);

    for (i = 0; i < k; i++) {
        printf("%d %s %d %d %d\n", i + 1, arr[i].name,
               arr[i].total, arr[i].a, arr[i].b);
    }

    free(arr);
    return 0;
}
